    private static int Find(int[] ranges, int scalar)
    {
        int left = 0, right = ranges.Length / 3 - 1;
        while (left <= right)
        {
            int middle = left + (right - left) / 2, index = middle * 3;
            if (scalar < ranges[index]) right = middle - 1;
            else if (scalar > ranges[index + 1]) left = middle + 1;
            else return ranges[index + 2];
        }
        return 0;
    }
